with flattened as (select id, log_ts, level, latency_ms, key, value from app_logs lateral view explode(context) x as key, value) select *, last_value(latency_ms, true) over w_recent as last_known_latency_ms, row_number() over (partition by key order by latency_ms, id, key) as row_seq, round(latency_ms / sum(latency_ms) over (partition by level), 4) as latency_ms_share from flattened window w_recent as (partition by key order by latency_ms, id, key rows between unbounded preceding and current row);
